import { renderElement } from "@ui-sdk/react/primitive"

import { cn } from "@/lib/cn"

import type { BadgeDotProps } from "./badge.types"
import { badgeDotVariants } from "./badge.variants"

export function BadgeDot({ color = "primary", pulse = false, className, render, ...props }: BadgeDotProps) {
  return renderElement(
    "span",
    {
      "aria-hidden": "true",
      ...props,
      "data-slot": "badge-dot",
      "data-color": color,
      "data-pulse": pulse || undefined,
      className: cn(badgeDotVariants({ color, pulse }), className),
    },
    render
  )
}

import { renderElement } from "@ui-sdk/react/primitive"

import { cn } from "@/lib/cn"

import type { BadgeTagProps } from "./badge.types"
import { badgeTagVariants } from "./badge.variants"

export function BadgeTag({ color = "primary", variant = "solid", className, render, ...props }: BadgeTagProps) {
  return renderElement(
    "span",
    {
      ...props,
      "data-slot": "badge-tag",
      "data-color": color,
      "data-variant": variant,
      className: cn(badgeTagVariants({ color, variant }), className),
    },
    render
  )
}

import type { ReactElement } from "react"
import { renderElement } from "@ui-sdk/react/primitive"
import { TooltipTrigger } from "@ui-sdk/react/tooltip"

// Import other registry components by exact file, not their folder's index.ts:
// the shadcn CLI rewrites `@/components/ui/tooltip` to `<ui>/tooltip/tooltip`.
import { Tooltip } from "@/components/ui/tooltip/tooltip"
import { TooltipContent } from "@/components/ui/tooltip/tooltip-content"
import { cn } from "@/lib/cn"

import type { BadgeProps } from "./badge.types"
import { badgeVariants } from "./badge.variants"

export function Badge({
  color = "primary",
  variant = "soft",
  size = "md",
  radius = "full",
  font,
  tooltip,
  tooltipOptions,
  className,
  render,
  ...props
}: BadgeProps) {
  const badgeProps = {
    ...props,
    "data-slot": "badge",
    "data-color": color,
    "data-variant": variant,
    "data-size": size,
    "data-radius": radius,
    className: cn(badgeVariants({ color, variant, size, radius, font }), className),
  }

  if (tooltip == null) return renderElement("span", badgeProps, render)

  const { delay, toggleable, type, className: contentClassName, ...contentProps } = tooltipOptions ?? {}
  // renderElement types its result's props as unknown; TooltipTrigger's render wants a props record.
  const trigger = renderElement("button", render == null ? { type: "button", ...badgeProps } : badgeProps, render) as ReactElement<
    Record<string, unknown>
  >

  // A tooltip needs a focusable trigger: without `render` the badge becomes a button, and a press
  // toggles the tip so touch screens can show it. The badge element goes in as `render` so it keeps its data-slot.
  return (
    <Tooltip delay={delay} toggleable={toggleable ?? render == null} type={type}>
      <TooltipTrigger render={trigger} />
      <TooltipContent {...contentProps} className={contentClassName}>
        {tooltip}
      </TooltipContent>
    </Tooltip>
  )
}

import type { ReactNode } from "react"
import type { PartProps } from "@ui-sdk/react/primitive"

import type { TooltipContentProps, TooltipProps } from "@/components/ui/tooltip/tooltip.types"
import type { IntentColor } from "@/lib/tokens.types"

/** Every intent color defined in the tokens. */
export type BadgeColor = IntentColor

/** `surface` is the neutral card pill (border, card fill, soft shadow); `color` only tints its text. */
export type BadgeVariant = "solid" | "soft" | "outline" | "surface"

/** `BadgeTag` has no `surface`: it's the colored chip inside one. */
export type BadgeTagVariant = Exclude<BadgeVariant, "surface">

/** `sm`: a compact chip, like a "New" next to a nav item. `md`: a pill with room for a tag, text and an icon. */
export type BadgeSize = "sm" | "md"

export type BadgeRadius = "none" | "sm" | "md" | "full"

export type BadgeFont = "sans" | "mono"

/** The tooltip settings a badge passes through. For anything else, compose `Tooltip` and `TooltipTrigger` yourself. */
export type BadgeTooltipOptions = Pick<TooltipProps, "delay" | "toggleable" | "type"> &
  Pick<TooltipContentProps, "side" | "align" | "sideOffset" | "arrow" | "className">

export type BadgeProps = {
  color?: BadgeColor
  variant?: BadgeVariant
  size?: BadgeSize
  radius?: BadgeRadius
  font?: BadgeFont
  /**
   * Wraps the badge in a Tooltip. A badge without `render` becomes a focusable button, and the
   * tooltip opens on press too (`toggleable`), so keyboard and touch reach it.
   */
  tooltip?: ReactNode
  tooltipOptions?: BadgeTooltipOptions
  className?: string
} & Omit<PartProps<"span">, "color" | "className">

export type BadgeTagProps = {
  /** Independent of the Badge's color. */
  color?: BadgeColor
  variant?: BadgeTagVariant
  className?: string
} & Omit<PartProps<"span">, "color" | "className">

export type BadgeDotProps = {
  color?: BadgeColor
  /** Pulses a ring around the dot, for live states. Off when the person prefers reduced motion. */
  pulse?: boolean
  className?: string
} & Omit<PartProps<"span">, "color" | "className" | "children">

import { cva } from "class-variance-authority"

import type { BadgeColor, BadgeFont, BadgeRadius, BadgeSize, BadgeTagVariant, BadgeVariant } from "./badge.types"

// Each color sets three local variables the variants read:
// --badge-color (fill), --badge-fg (text on the fill), --badge-accent (text, borders and dots on light
// fills: the intent's -text token, which keeps 4.5:1 where the fill color wouldn't).
// The tag and the dot set their own, so they never inherit the badge's color.
const colorClasses = {
  primary: "[--badge-color:var(--primary)] [--badge-fg:var(--primary-foreground)] [--badge-accent:var(--primary-text)]",
  secondary: "[--badge-color:var(--secondary)] [--badge-fg:var(--secondary-foreground)] [--badge-accent:var(--secondary-text)]",
  muted: "[--badge-color:var(--muted)] [--badge-fg:var(--muted-text)] [--badge-accent:var(--muted-text)]",
  info: "[--badge-color:var(--info)] [--badge-fg:var(--info-foreground)] [--badge-accent:var(--info-text)]",
  warning: "[--badge-color:var(--warning)] [--badge-fg:var(--warning-foreground)] [--badge-accent:var(--warning-text)]",
  success: "[--badge-color:var(--success)] [--badge-fg:var(--success-foreground)] [--badge-accent:var(--success-text)]",
  error: "[--badge-color:var(--error)] [--badge-fg:var(--error-foreground)] [--badge-accent:var(--error-text)]",
} satisfies Record<BadgeColor, string>

// The `[a&]` / `[button&]` hovers apply only when the badge renders as a link or button.
const variantClasses = {
  solid: "bg-(--badge-color) text-(--badge-fg) [a&]:hover:bg-(--badge-color)/90 [button&]:hover:bg-(--badge-color)/90",
  soft: "bg-(--badge-accent)/15 text-(--badge-accent) [a&]:hover:bg-(--badge-accent)/25 [button&]:hover:bg-(--badge-accent)/25",
  outline: "border border-(--badge-accent)/40 text-(--badge-accent) [a&]:hover:bg-(--badge-accent)/10 [button&]:hover:bg-(--badge-accent)/10",
  surface: "border border-border bg-card/70 text-(--badge-accent) shadow-soft backdrop-blur [a&]:hover:bg-accent [button&]:hover:bg-accent",
} satisfies Record<BadgeVariant, string>

// A leading BadgeTag pulls the start padding in, so the pill hugs the chip.
const sizeClasses = {
  sm: "gap-1 px-1 py-0.5 text-3xs has-[>[data-slot=badge-tag]:first-child]:ps-0.5",
  md: "gap-2 px-3 py-1 text-xs font-medium has-[>[data-slot=badge-tag]:first-child]:ps-1",
} satisfies Record<BadgeSize, string>

const radiusClasses = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  full: "rounded-full",
} satisfies Record<BadgeRadius, string>

const fontClasses = {
  sans: "font-sans",
  mono: "font-mono",
} satisfies Record<BadgeFont, string>

export const badgeVariants = cva(
  [
    "group/badge inline-flex w-fit shrink-0 items-center whitespace-nowrap",
    "[&_svg]:size-3 [&_svg]:shrink-0",
    "transition-[color,background-color,border-color] duration-150 ease-out motion-reduce:transition-none",
    "outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
    "[button&]:cursor-pointer",
  ].join(" "),
  {
    variants: {
      color: colorClasses,
      variant: variantClasses,
      size: sizeClasses,
      radius: radiusClasses,
      font: fontClasses,
    },
    defaultVariants: { color: "primary", variant: "soft", size: "md", radius: "full" },
  }
)

const tagVariantClasses = {
  solid: "bg-(--badge-color) text-(--badge-fg)",
  soft: "bg-(--badge-accent)/15 text-(--badge-accent)",
  outline: "border border-(--badge-accent)/40 text-(--badge-accent)",
} satisfies Record<BadgeTagVariant, string>

// The tag follows its badge's size and radius; outside a badge it's a small round chip.
export const badgeTagVariants = cva(
  [
    "inline-flex shrink-0 items-center rounded-full px-2 py-0.5 text-3xs font-semibold tracking-wide uppercase",
    "group-data-[size=sm]/badge:px-1 group-data-[size=sm]/badge:py-0",
    "group-data-[radius=none]/badge:rounded-none group-data-[radius=sm]/badge:rounded-sm group-data-[radius=md]/badge:rounded-sm",
  ].join(" "),
  {
    variants: {
      color: colorClasses,
      variant: tagVariantClasses,
    },
    defaultVariants: { color: "primary", variant: "solid" },
  }
)

export const badgeDotVariants = cva(
  "relative inline-block size-1.5 shrink-0 rounded-full bg-(--badge-accent)",
  {
    variants: {
      color: colorClasses,
      pulse: {
        true: "before:absolute before:inset-0 before:rounded-full before:bg-inherit motion-safe:before:animate-ping",
        false: "",
      },
    },
    defaultVariants: { color: "primary", pulse: false },
  }
)
